const body = $input.first().json.body;
const required = ['freelancer_name', 'client_name', 'project_description', 'payment_amount', 'currency'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const amount = parseFloat(body.payment_amount);
if (isNaN(amount) || amount <= 0) return [{ json: { valid: false, error: 'payment_amount must be positive' } }];
const contractTypes = ['fixed_price', 'hourly', 'retainer', 'milestone_based', 'revenue_share'];
const contractType = contractTypes.includes(body.contract_type) ? body.contract_type : 'fixed_price';
const jurisdictions = ['us_general', 'uk', 'eu', 'canada', 'australia', 'us_california', 'international'];
const jurisdiction = jurisdictions.includes(body.jurisdiction) ? body.jurisdiction : 'us_general';
return [{ json: {
  valid: true,
  freelancerName: body.freelancer_name.trim(),
  freelancerEmail: body.freelancer_email || '',
  freelancerAddress: body.freelancer_address || '',
  freelancerBusinessName: body.freelancer_business_name || '',
  clientName: body.client_name.trim(),
  clientEmail: body.client_email || '',
  clientAddress: body.client_address || '',
  clientContactName: body.client_contact_name || '',
  projectDescription: body.project_description.trim().slice(0, 1500),
  deliverables: Array.isArray(body.deliverables) ? body.deliverables : (body.deliverables || '').split('\n').map(d=>d.trim()).filter(Boolean),
  contractType,
  paymentAmount: amount,
  currency: body.currency,
  paymentSchedule: body.payment_schedule || '',
  paymentTermsDays: parseInt(body.payment_terms_days) || 14,
  startDate: body.start_date || '',
  endDate: body.end_date || '',
  jurisdiction,
  includeIPClause: body.include_ip_clause !== false,
  includeNDA: body.include_nda === true || body.include_nda === 'true',
  includeNonCompete: body.include_non_compete === true || body.include_non_compete === 'true',
  revisionRounds: parseInt(body.revision_rounds) || 2,
  lateFeePercent: parseFloat(body.late_fee_percent) || 1.5,
  specialTerms: (body.special_terms || '').slice(0, 600),
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

