Freelancer: {{ $json.freelancerName }}{{ $json.freelancerBusinessName ? ' (' + $json.freelancerBusinessName + ')' : '' }}
Freelancer email: {{ $json.freelancerEmail || 'not provided' }}
Freelancer address: {{ $json.freelancerAddress || 'not provided' }}

Client: {{ $json.clientName }}{{ $json.clientContactName ? ' (Contact: ' + $json.clientContactName + ')' : '' }}
Client email: {{ $json.clientEmail || 'not provided' }}
Client address: {{ $json.clientAddress || 'not provided' }}

Contract type: {{ $json.contractType.replace(/_/g,' ') }}
Jurisdiction: {{ $json.jurisdiction.replace(/_/g,' ') }}
Payment: {{ $json.currency }}{{ $json.paymentAmount }} {{ $json.paymentSchedule ? '— ' + $json.paymentSchedule : '' }}
Payment terms: Net {{ $json.paymentTermsDays }} days
Late fee: {{ $json.lateFeePercent }}% per month
Start date: {{ $json.startDate || 'to be agreed' }}
End date: {{ $json.endDate || 'on project completion' }}
Revision rounds: {{ $json.revisionRounds }}

Project description:
{{ $json.projectDescription }}

Deliverables:
{{ $json.deliverables.map((d,i) => `${i+1}. ${d}`).join('\n') || 'as described in project description' }}

Include IP assignment clause: {{ $json.includeIPClause }}
Include NDA: {{ $json.includeNDA }}
Include non-compete: {{ $json.includeNonCompete }}
Special terms: {{ $json.specialTerms || 'none' }}

Return this JSON:
{
  "contract_title": "FREELANCE SERVICES AGREEMENT",
  "effective_date_placeholder": "[ DATE ]",
  "sections": [
    {
      "section_number": "1",
      "title": "PARTIES",
      "content": "full section text"
    }
  ],
