    "termination": "plain English summary of termination and kill fee terms"
  },
  "red_flags_for_review": ["things the freelancer should have a lawyer review before signing — specific to this contract"],
  "client_obligations": ["key obligations placed on the client in this contract"],
  "freelancer_protections": ["key protections included for the freelancer"]
}

Required sections to include:
1. Parties
2. Services & Deliverables (specific scope)
3. Timeline & Milestones
4. Payment Terms (including late fees, kill fee if applicable)
5. Revisions & Change Orders
6. Intellectual Property{{ ' (include IP assignment clause)' if True else '' }}
7. Independent Contractor Status
8. Confidentiality{{ ' + NDA clause' if True else '' }}
9. Limitation of Liability
10. Termination
11. Dispute Resolution ({{ $json.jurisdiction.replace(/_/g,' ') }})
12. General Provisions

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let contract;
try { contract = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
contract._meta = { freelancerName: input.freelancerName, clientName: input.clientName, projectDescription: input.projectDescription.slice(0,100), paymentAmount: input.paymentAmount, currency: input.currency, jurisdiction: input.jurisdiction, replyEmail: input.replyEmail };
return [{ json: contract }];

const c = $input.first().json;
const m = c._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const sectionBlocks = (c.sections||[]).map(s => `
  <div style="margin-bottom:24px">
    <div style="font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#1a1a1a;border-bottom:1px solid #e5e7eb;padding-bottom:6px;margin-bottom:10px">${esc(s.section_number)}. ${esc(s.title)}</div>
    <div style="font-size:14px;line-height:1.8;color:#374151;white-space:pre-wrap">${esc(s.content)}</div>
  </div>`).join('');

const redFlags = (c.red_flags_for_review||[]).map(f => `<li style="font-size:13px;margin-bottom:6px;line-height:1.5;color:#7f1d1d">${esc(f)}</li>`).join('');
const protections = (c.freelancer_protections||[]).map(p => `<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #f0fdf4;color:#166534">✓ ${esc(p)}</div>`).join('');
const clientObligations = (c.client_obligations||[]).map(o => `<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #f0f9ff;color:#1e40af">• ${esc(o)}</div>`).join('');

const kt = c.key_terms_summary || {};

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f0;font-family:Georgia,'Times New Roman',serif;color:#1a1a1a">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#1c1917;color:#fff;padding:22px 32px;border-radius:10px 10px 0 0;text-align:center">
    <div style="font-size:20px;font-weight:700;letter-spacing:1px">${esc(c.contract_title||'FREELANCE SERVICES AGREEMENT')}</div>
    <div style="font-size:13px;color:#78716c;margin-top:5px">Effective Date: ${esc(c.effective_date_placeholder||'[ DATE ]')}</div>
  </div>
  <div style="background:#fff;padding:16px 32px;border:1px solid #e7e5e4;border-top:none">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;font-size:13px">
      <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Payment</div><div style="color:#374151;line-height:1.6">${esc(kt.payment||'')}</div></div>
      <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">IP ownership</div><div style="color:#374151;line-height:1.6">${esc(kt.ip_ownership||'')}</div></div>
      <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Revisions</div><div style="color:#374151;line-height:1.6">${esc(kt.revisions||'')}</div></div>
      <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Termination</div><div style="color:#374151;line-height:1.6">${esc(kt.termination||'')}</div></div>
    </div>
  </div>
  <div style="background:#fff;padding:22px 32px;border:1px solid #e7e5e4;border-top:3px solid #f5f5f0;font-family:Georgia,serif">
    ${sectionBlocks}
    <div style="margin-top:32px;padding-top:20px;border-top:1px solid #e7e5e4">
      <div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#9ca3af;margin-bottom:12px">Signatures</div>
      <div style="white-space:pre-wrap;font-size:14px;line-height:2">${esc(c.signature_block||'')}</div>
    </div>
  </div>
  ${protections ? `<div style="background:#f0fdf4;padding:14px 32px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:8px">Freelancer protections in this contract</div>
    ${protections}
  </div>` : ''}
  ${clientObligations ? `<div style="background:#eff6ff;padding:14px 32px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px">Client obligations</div>
    ${clientObligations}
  </div>` : ''}
  ${redFlags ? `<div style="background:#fef2f2;padding:14px 32px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:8px">Review with a lawyer before signing</div>
    <ul style="padding-left:18px;margin:0">${redFlags}</ul>
    <div style="font-size:12px;color:#9ca3af;margin-top:10px;font-family:sans-serif">This contract is a starting point and not legal advice. Review with a qualified attorney in your jurisdiction.</div>
  </div>` : ''}
  <div style="background:#1c1917;color:#57534e;font-size:11px;padding:12px 32px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Freelance Contract Generator · Not legal advice · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, freelancerName: m.freelancerName, clientName: m.clientName, paymentAmount: m.paymentAmount, currency: m.currency, contract: c } }];
